using System.Security.Claims;using Microsoft.AspNetCore.Identity;using Microsoft.EntityFrameworkCore;
namespace AuthService.Data;
public static class DatabaseInitializer { public static async Task InitializeAsync(IServiceProvider services,IConfiguration config,ILogger logger){using var scope=services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AuthDbContext>();var roles=scope.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>();var users=scope.ServiceProvider.GetRequiredService<UserManager<IdentityUser>>();var tries=0;while(true){try{await db.Database.EnsureCreatedAsync();break;}catch when(++tries<40){await Task.Delay(TimeSpan.FromSeconds(3));}}var matrix=new Dictionary<string,string[]>{["Candidate"]=["catalog.read","registrations.create","profile.read"],["Examiner"]=["catalog.read","catalog.manage","registrations.read","registrations.create","profile.read"],["Administrator"]=["catalog.read","catalog.manage","registrations.read","registrations.create","profile.read","users.manage"]};foreach(var (name,permissions) in matrix){var role=await roles.FindByNameAsync(name);if(role is null){role=new IdentityRole(name);await roles.CreateAsync(role);}var old=await roles.GetClaimsAsync(role);foreach(var claim in old.Where(x=>x.Type=="permission"))await roles.RemoveClaimAsync(role,claim);foreach(var permission in permissions)await roles.AddClaimAsync(role,new Claim("permission",permission));}var email=config["BootstrapAdmin:Email"];var password=config["BootstrapAdmin:Password"];if(!string.IsNullOrWhiteSpace(email)&&!string.IsNullOrWhiteSpace(password)&&await users.FindByEmailAsync(email)is null){var admin=new IdentityUser{UserName=email,Email=email,EmailConfirmed=true};var result=await users.CreateAsync(admin,password);if(result.Succeeded)await users.AddToRoleAsync(admin,"Administrator");else logger.LogError("Bootstrap administrator creation failed: {Errors}",string.Join("; ",result.Errors.Select(x=>x.Description)));}} }